-- 026_question_lifecycle_slimming: lifecycle belongs to the stable question identity.
-- Preserve every historical score, concept and review fact. Only old approved rows start enabled.
-- Nullable staging distinguishes unfinished backfills from later administrator lifecycle changes.
-- The successor retains the complete effective 025 question probe, including nullable score and old indexes.

-- @step add_question_enabled
-- @replaces-check 025_question_bank_without_scores/question_score_nullable
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question') = 21 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question' AND ((COLUMN_NAME IN ('regulation_id', 'version_id', 'category_id', 'concept_id', 'current_version_id') AND DATA_TYPE = 'bigint' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'difficulty' AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME IN ('type', 'source') AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'score' AND COLUMN_TYPE = 'decimal(5,2)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL AND EXTRA = '' AND COLUMN_COMMENT = '历史兼容列；新题及修订为 NULL，实际分值另存试卷'))) = 9 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question' AND ((INDEX_NAME = 'idx_question_category_pool' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'category_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_category_pool' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'status' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_category_pool' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 3 AND COLUMN_NAME = 'type' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_category_pool' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 4 AND COLUMN_NAME = 'difficulty' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_concept' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'concept_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_current_version' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'current_version_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL))) = 6 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question' AND INDEX_NAME = 'idx_question_category_pool') = 4 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question' AND INDEX_NAME = 'idx_question_concept') = 1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question' AND INDEX_NAME = 'idx_question_current_version') = 1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='question' AND ((COLUMN_NAME='content_schema_version' AND COLUMN_TYPE='tinyint unsigned' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='1') OR (COLUMN_NAME='content_json' AND DATA_TYPE='json' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL)))=2 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='question' AND COLUMN_NAME='is_enabled' AND COLUMN_TYPE='tinyint(1)' AND EXTRA='' AND ((IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL) OR (IS_NULLABLE='NO' AND COLUMN_DEFAULT='1')))=1 THEN 1 ELSE 0 END AS complete;
ALTER TABLE question ADD COLUMN is_enabled TINYINT(1) NULL AFTER current_version_id;

-- @step initialize_question_enabled
-- @check SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM question WHERE is_enabled IS NULL) THEN 1 ELSE 0 END AS complete;
UPDATE question SET is_enabled=CASE WHEN status='approved' THEN 1 ELSE 0 END, updated_at=updated_at WHERE is_enabled IS NULL;

-- @step finalize_question_enabled
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='question' AND COLUMN_NAME='is_enabled' AND COLUMN_TYPE='tinyint(1)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='1' AND EXTRA='')=1 THEN 1 ELSE 0 END AS complete;
ALTER TABLE question MODIFY COLUMN is_enabled TINYINT(1) NOT NULL DEFAULT 1;

-- @step index_question_enabled_pool
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='question' AND INDEX_NAME='idx_question_enabled_pool')=5 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='question' AND INDEX_NAME='idx_question_enabled_pool' AND NON_UNIQUE=1 AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL AND ((SEQ_IN_INDEX=1 AND COLUMN_NAME='is_enabled') OR (SEQ_IN_INDEX=2 AND COLUMN_NAME='category_id') OR (SEQ_IN_INDEX=3 AND COLUMN_NAME='type') OR (SEQ_IN_INDEX=4 AND COLUMN_NAME='difficulty') OR (SEQ_IN_INDEX=5 AND COLUMN_NAME='current_version_id')))=5 THEN 1 ELSE 0 END AS complete;
ALTER TABLE question ADD INDEX idx_question_enabled_pool (is_enabled,category_id,type,difficulty,current_version_id);
